def dedup(a):
    r = []
    for x in a:
        if x not in r: r.append(x)
    return r

def unused_vars(code):
    import ast
    names, used = set(), set()
    t = ast.parse(code)
    for n in ast.walk(t):
        if isinstance(n, ast.Name):
            (used if isinstance(n.ctx, ast.Load) else names).add(n.id)
    return names - used

def sim_trigram(a, b):
    def tri(s): return {s[i:i+3] for i in range(len(s)-2)}
    x, y = tri(a), tri(b)
    return len(x & y) / max(len(x | y), 1)

def tree_depth(root):
    if root is None: return 0
    return 1 + max(tree_depth(root.left), tree_depth(root.right))

def bubble(a):
    a = list(a)
    for i in range(len(a)-1):
        for j in range(len(a)-1-i):
            if a[j] > a[j+1]: a[j], a[j+1] = a[j+1], a[j]
    return a
